// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // Ensure the array length does not exceed maxNodeDelegatorCount (10) by assumption
        vm.assume(nodeDelegatorContracts.length <= 10);
        // Ensure all addresses are non-zero
        for (uint i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        bool pausedBefore = c.paused();

        // Call addNodeDelegatorContractToQueue, which may revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("addNodeDelegatorContractToQueue(address[])", nodeDelegatorContracts));

        // If the call succeeded, then paused() must remain unchanged
        if (success) {
            bool pausedAfter = c.paused();
            assertTrue(pausedBefore == pausedAfter, "paused() changed after addNodeDelegatorContractToQueue");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        vm.assume(nodeDelegatorContracts.length > 0);
        // Ensure addresses are non-zero and not the contract itself to avoid unintended issues
        for (uint i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }
        // Call addNodeDelegatorContractToQueue
        c.addNodeDelegatorContractToQueue(nodeDelegatorContracts);
        // After the call, paused() must return false
        assertTrue(!c.paused());
    }
}

