pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // Ensure no zero addresses
        for (uint256 i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }
        // Bound: nodeDelegatorQueue length + input length <= maxNodeDelegatorCount (10)
        uint256 initialQueueLength = c.getNodeDelegatorQueue().length;
        vm.assume(nodeDelegatorContracts.length <= 10 - initialQueueLength);

        bool pausedBefore = c.paused();
        c.addNodeDelegatorContractToQueue(nodeDelegatorContracts);
        bool pausedAfter = c.paused();
        assertTrue(pausedBefore == pausedAfter);
    }
}

