// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata nodeDelegatorContracts) public {
        // Initialize the contract with a dummy lrtConfig address
        address dummyConfig = address(0x1234);
        // The initialize function requires the caller to be the admin; we use prank to set msg.sender
        vm.prank(address(this));
        c.initialize(dummyConfig);

        // Record the lrtConfig before the call
        address lrtConfigBefore = c.lrtConfig();

        // Call addNodeDelegatorContractToQueue; it may revert, so we wrap in try/catch
        bool callReverted = false;
        try c.addNodeDelegatorContractToQueue(nodeDelegatorContracts) {
            // success
        } catch {
            callReverted = true;
        }

        // The rule: the call should not change lrtConfig (regardless of revert or not)
        address lrtConfigAfter = c.lrtConfig();
        assertTrue(lrtConfigBefore == lrtConfigAfter, "lrtConfig changed after addNodeDelegatorContractToQueue");
    }
}

