pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _contracts) public {
        // Initialize with a known address
        address lrtConfigAddr = makeAddr("lrtConfig");
        c.initialize(lrtConfigAddr);
        address initialLrtConfig = address(c.lrtConfig());

        // Bound the array length to avoid out-of-gas issues
        vm.assume(_contracts.length <= 10);
        for (uint256 i = 0; i < _contracts.length; i++) {
            vm.assume(_contracts[i] != address(0));
        }

        // Call addNodeDelegatorContractToQueue
        c.addNodeDelegatorContractToQueue(_contracts);

        // Assert: lrtConfig remains unchanged
        assertTrue(initialLrtConfig == address(c.lrtConfig()));
    }
}

