    function setUp() public { c = new C(); }
    function testFuzz_property(address asset) public {
        // Ensure asset is not zero address (to avoid issues)
        vm.assume(asset != address(0));

        // Add some node delegator contracts to the queue to exercise the code path
        address[] memory ndcs = new address[](1);
        ndcs[0] = address(1); // a dummy contract address (non-zero)
        // Bound the call so that the queue does not exceed maxNodeDelegatorCount
        if (c.nodeDelegatorQueue().length < c.maxNodeDelegatorCount()) {
            c.addNodeDelegatorContractToQueue(ndcs);
        }

        // Get the distribution data directly
        (uint256 assetLyingInDepositPool, uint256 assetLyingInNDCs, ) = c.getAssetDistributionData(asset);
        uint256 totalDeposits = c.getTotalAssetDeposits(asset);

        // The rule: totalDeposits should be at least assetLyingInDepositPool + assetLyingInNDCs
        // (In the buggy version, assetStakedInEigenLayer is subtracted, potentially making totalDeposits smaller)
        assertTrue(totalDeposits >= assetLyingInDepositPool + assetLyingInNDCs);
    }
}

