pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address asset, uint256[] memory ndcList) public {
        // Ensure asset is supported to avoid revert in getAssetDistributionData
        vm.assume(asset != address(0));
        // We can't call isSupportedAsset directly because we don't have a real LRT config.
        // Instead, we bound the node delegator list to be empty so the pool balance is the only component.
        // But to test the general rule, we need at least one node delegator to have a difference.
        // Since we cannot set up a full environment, we rely on the fact that for any asset,
        // the reference adds all three components, so the sum is >= the first two.
        // The bug subtracts the third, so the assertion will fail when assetStakedInEigenLayer > 0.
        // With an empty queue, assetStakedInEigenLayer is zero, so both are equal, and the test passes.
        // To trigger the bug, we need a non-empty queue. We'll add a dummy ND with zero balance.
        // Since we lack a real node delegator contract, we'll simulate by adding a random address.
        // But then getAssetBalance will revert (no code), so we skip that.
        // The only reliable way: the bug returns assetLyingInDepositPool + assetLyingInNDCs - assetStakedInEigenLayer.
        // For the reference, assetStakedInEigenLayer is always >= 0, so it's >= the pool+NDCs.
        // For the bug, if assetStakedInEigenLayer > 0, it's strictly less.
        // Since we cannot produce staked amounts, we skip the test for non-empty queue.
        // Instead, we assert a property that holds for any state: 
        // The total deposits should be at least as large as the pool balance.
        // This is true for reference (adds all three), but bug could subtract and become less.

        // We'll just use pool balance as a lower bound.
        uint256 poolBalance = IERC20(asset).balanceOf(address(c));
        (uint256 pool, uint256 ndcs, uint256 staked) = c.getAssetDistributionData(asset);
        uint256 total = c.getTotalAssetDeposits(asset);
        // In reference, total = pool + ndcs + staked >= pool
        // In bug, total = pool + ndcs - staked could be less than pool if staked > ndcs
        assertTrue(total >= pool, "Total deposits should be at least the amount in the deposit pool");
    }
}

